        [32281, 'Kimi no Na wa.', 'Your Name.', '君の名は。', 'https://myanimelist.cdn-dena.com/images/anime/5/87048.jpg', 2, 'Original', 1, 'Finished Airing', '2016-08-26', '2016-08-26', 106, 3, '9.19', 471398, 2, 33, 730076, 34912, null, null, null, null],
        [20, 'Naruto', 'Naruto', 'ナルト', 'https://myanimelist.cdn-dena.com/images/anime/13/17405.jpg', 1, 'Manga', 220, 'Finished Airing', '2002-10-03', '2007-02-08', 23, 3, '7.88', 648605, 745, 10, 980265, 34468, 'Naruto received numerous awards during its airing, including the "Best Full-Length Animation Program Award" in the Third UStv Awards and the 38th "Best Animated Show" in IGN&#039;s Top 100 Animated Series.', 'Fall', 2002, 'Thursdays at 19:30 (JST)'],
        [28851, 'Koe no Katachi', 'A Silent Voice', '聲の形', 'https://myanimelist.cdn-dena.com/images/anime/3/80136.jpg', 2, 'Manga', 1, 'Finished Airing', '2016-09-17', '2016-09-17', 130, 3, '9.04', 296261, 12, 77, 511915, 19815, null, null, null, null],
        [199, 'Sen to Chihiro no Kamikakushi', 'Spirited Away', '千と千尋の神隠し', 'https://myanimelist.cdn-dena.com/images/anime/6/79597.jpg', 2, 'Original', 1, 'Finished Airing', '2001-07-20', '2001-07-20', 125, 2, '8.92', 498602, 19, 39, 705769, 15412, 'Sen to Chihiro no Kamikakushi is the highest grossing film in Japanese history, with a total of ￥30.4 billion from Japanese box office sales alone. It is also the most successful film to debut from Japan, with a total of $289 million worldwide. This critically acclaimed film has won numerous awards, including the Academy Award, more commonly known as "Oscar", for Best Animated Feature at the 75th Academy Awards in 2003, as well as the Golden Bear at the 2002 Berlin International Film Festival (alongside Bloody Sunday). It is also among the top ten in the British Film Institute&#039;s list of the "50 films you should see by the age of 14". The English version of Sen to Chihiro no Kamikakushi was dubbed by Walt Disney Pictures and premiered in 2002. The film was released on DVD and VHS formats in North America by Buena Vista Home Entertainment in 2003.', null, null, null],
        [21469, 'Stand By Me Doraemon', null, 'STAND BY ME ドラえもん', 'https://myanimelist.cdn-dena.com/images/anime/9/65571.jpg', 2, 'Manga', 1, 'Finished Airing', '2014-08-08', '2014-08-08', 95, 2, '8.13', 6520, 406, 3636, 10320, 47, null, null, null, null],
        [31490, 'One Piece Film: Gold', null, 'ONE PIECE FILM GOLD', 'https://myanimelist.cdn-dena.com/images/anime/12/81081.jpg', 2, 'Manga', 1, 'Finished Airing', '2016-07-23', '2016-07-23', 120, 3, '8.14', 30925, 384, 1409, 56534, 138, null, null, null, null],
        [270, 'Hellsing', 'Hellsing', 'Hellsing [ヘルシング]', 'https://myanimelist.cdn-dena.com/images/anime/10/19956.jpg', 1, 'Manga', 13, 'Finished Airing', '2001-10-11', '2002-01-17', 23, 4, '7.60', 220299, 1349, 125, 395276, 4823, 'Hellsing was based on Kouta Hirano&rsquo;s manga of the same name. The anime utilizes the same characters but the story strongly deviates from the manga, which was still ongoing at the time of the anime&rsquo;s creation.', 'Fall', 2001, 'Unknown'],
        [120, 'Fruits Basket', 'Fruits Basket', 'フルーツバスケット', 'https://myanimelist.cdn-dena.com/images/anime/4/75204.jpg', 1, 'Manga', 26, 'Finished Airing', '2001-07-05', '2001-12-27', 24, 3, '7.77', 167968, 939, 222, 292572, 7579, 'Fruits Basket won the 2001 Animage&#039;s Anime Grand Prix Award.', 'Summer', 2001, 'Thursdays at 18:00 (JST)'],
        [154, 'Shaman King', 'Shaman King', 'シャーマンキング', 'https://myanimelist.cdn-dena.com/images/anime/4/18990.jpg', 1, 'Manga', 64, 'Finished Airing', '2001-07-04', '2002-09-25', 23, 3, '7.83', 120613, 833, 343, 215353, 2829, null, 'Summer', 2001, 'Wednesdays at 18:30 (JST)'],
        [874, 'Digimon Tamers', 'Digimon Tamers', 'デジモンテイマーズ', 'https://myanimelist.cdn-dena.com/images/anime/7/73696.jpg', 1, 'Original', 51, 'Finished Airing', '2001-04-01', '2002-03-31', 25, 2, '7.65', 74655, 1215, 725, 118662, 1196, 'Digimon Tamers is the first anime of the franchise to depart from the original storyline established in Digimon Adventure and Digimon Adventure 02. The trading cards used by the characters in the show are based on cards in the real life Digimon Trading Card Game.', 'Spring', 2001, 'Sundays at 09:00 (JST)'],
        [11757, 'Sword Art Online', 'Sword Art Online', 'ソードアート・オンライン', 'https://myanimelist.cdn-dena.com/images/anime/11/39717.jpg', 1, 'Light novel', 25, 'Finished Airing', '2012-07-08', '2012-12-23', 23, 3, '7.64', 915986, 1259, 3, 1301616, 50042, 'Sword Art Online adapts the first 4 novels of Reki Kawahara&#039;s light novel series of the same name.The first episode received an early screening at the Tokyo International Forum Hall C on June 24, 2012. The regular TV broadcast started July 8, 2012.', 'Summer', 2012, 'Sundays at 00:00 (JST)'],
        [11111, 'Another', 'Another', 'アナザー', 'https://myanimelist.cdn-dena.com/images/anime/4/75509.jpg', 1, 'Novel', 12, 'Finished Airing', '2012-01-10', '2012-03-27', 24, 4, '7.77', 469764, 933, 26, 769742, 11406, 'Pre-screening on 26 December 2011. The regular TV airing started on 09 January 2012.', 'Winter', 2012, 'Unknown'],
        [13601, 'Psycho-Pass', 'Psycho-Pass', 'サイコパス', 'https://myanimelist.cdn-dena.com/images/anime/5/43399.jpg', 1, 'Original', 22, 'Finished Airing', '2012-10-12', '2013-03-22', 23, 4, '8.45', 377003, 134, 29, 751118, 24112, 'An edited version of the series received a rebroadcast starting July 10, 2014. 22 episodes of the original series were combined into eleven 46-minute long episodes with some scenes being slightly extended. Psycho-Pass aired on Fuji Television&#039;s noitaminA block. In the 2013 Newtype Anime Awards it was voted as fourth best title of the year. It&#039;s 11th episode was awarded "Best Episode" in the Noitamina 10th anniversary fan vote. It has spawned several video-game spin-offs, a novel series and a manga series as well.', 'Fall', 2012, 'Fridays at 00:45 (JST)'],
        [11617, 'High School DxD', 'High School DxD', 'ハイスクールD×D', 'https://myanimelist.cdn-dena.com/images/anime/2/32527.jpg', 1, 'Light novel', 12, 'Finished Airing', '2012-01-06', '2012-03-23', 24, 5, '7.62', 371603, 1294, 56, 587381, 13007, 'High School DxD is known for its award winning English dub. At the Behind the Voice Actors Awards, Jamie Marchi won "Best Female Lead Vocal Performance in an Anime Television Series/OVA" in 2014. The series also won  "Best Vocal Ensemble in an Anime Television Series/OVA" in 2015 for season 2.', 'Winter', 2012, 'Fridays at 11:00 (JST)'],
        [22319, 'Tokyo Ghoul', 'Tokyo Ghoul', '東京喰種-トーキョーグール-', 'https://myanimelist.cdn-dena.com/images/anime/5/64449.jpg', 1, 'Manga', 12, 'Finished Airing', '2014-07-04', '2014-09-19', 24, 4, '8.00', 659308, 560, 6, 1013138, 28883, null, 'Summer', 2014, 'Fridays at 00:00 (JST)'],
        [19815, 'No Game No Life', 'No Game, No Life', 'ノーゲーム・ノーライフ', 'https://myanimelist.cdn-dena.com/images/anime/5/65187.jpg', 1, 'Light novel', 12, 'Finished Airing', '2014-04-09', '2014-06-25', 23, 3, '8.41', 623227, 162, 11, 970460, 31782, 'No Game No Life adapts the first three volumes of Yuu Kamiya&#039;s light novel series of the same title.', 'Spring', 2014, 'Wednesdays at 21:30 (JST)'],
        [20507, 'Noragami', 'Noragami: Stray God', 'ノラガミ', 'https://myanimelist.cdn-dena.com/images/anime/9/77809.jpg', 1, 'Manga', 12, 'Finished Airing', '2014-01-05', '2014-03-23', 24, 3, '8.15', 502213, 377, 15, 846498, 18501, 'Aside from the anime and manga there is a mobile game titled Noragami -Kami to Enishi-.', 'Winter', 2014, 'Sundays at 23:30 (JST)'],
        [21881, 'Sword Art Online II', 'Sword Art Online II', 'ソードアート・オンライン II', 'https://myanimelist.cdn-dena.com/images/anime/11/65185.jpg', 1, 'Light novel', 24, 'Finished Airing', '2014-07-05', '2014-12-20', 23, 3, '7.20', 531486, 2827, 17, 830508, 7931, 'Sword Art Online II adapts novels 5 to 8 of Reki Kawahara&#039;s light novel series of the same title.The first episode was screened at various special events held in the United States, France, Germany, Hong Kong, Taiwan, Korea and Japan before its television premiere.', 'Summer', 2014, 'Mondays at 00:00 (JST)'],
        [31964, 'Boku no Hero Academia', 'My Hero Academia', '僕のヒーローアカデミア', 'https://myanimelist.cdn-dena.com/images/anime/10/78745.jpg', 1, 'Manga', 13, 'Finished Airing', '2016-04-03', '2016-06-26', 24, 3, '8.44', 494037, 137, 27, 763973, 19712, 'Mangaka Horikoushi Kouhei has noted that American superhero comics are the inspiration for the series, and has based character pages on logos for Marvel and DC comic characters.', 'Spring', 2016, 'Sundays at 17:00 (JST)'],
        [31240, 'Re:Zero kara Hajimeru Isekai Seikatsu', 'Re:ZERO -Starting Life in Another World-', 'Re：ゼロから始める異世界生活', 'https://myanimelist.cdn-dena.com/images/anime/11/79410.jpg', 1, 'Light novel', 25, 'Finished Airing', '2016-04-04', '2016-09-19', 25, 4, '8.43', 438250, 153, 36, 720575, 27120, 'Re:Zero adapts the first 9 volumes of Tappei Nagatsuki&#039;s light novel series of the same title.', 'Spring', 2016, 'Mondays at 01:05 (JST)'],
        [31043, 'Boku dake ga Inai Machi', 'ERASED', '僕だけがいない街', 'https://myanimelist.cdn-dena.com/images/anime/10/77957.jpg', 1, 'Manga', 12, 'Finished Airing', '2016-01-08', '2016-03-25', 23, 4, '8.56', 440402, 77, 40, 699351, 21248, 'Boku dake ga Inai Machi is based on Kei Sanbe&#039;s manga series of the same title. The anime adapts the full story of the manga, though it condenses and alters the events that take place in volumes 6 to 8.<br /> <br /> The first two episodes were shown at an event on January 5, 2016, at Shinjuku Ward 9. A live-action movie adaptation was released in Japan on March 19, 2016 which also featured an alternate ending. A live-action Netflix TV series was released on December 15, 2017.', 'Winter', 2016, 'Fridays at 00:55 (JST)'],
        [30831, 'Kono Subarashii Sekai ni Shukufuku wo!', 'KonoSuba: God&#039;s Blessing on This Wonderful World!', 'この素晴らしい世界に祝福を！', 'https://myanimelist.cdn-dena.com/images/anime/8/77831.jpg', 1, 'Light novel', 10, 'Finished Airing', '2016-01-14', '2016-03-17', 23, 3, '8.16', 359121, 361, 58, 580873, 13592, 'Kono Subarashii Sekai ni Shukufuku wo! adapts the first 2 volumes of Natsume Akatsuki&#039;s light novel series of the same name.', 'Winter', 2016, 'Thursdays at 01:05 (JST)'],
        [777, 'Hellsing Ultimate', 'Hellsing Ultimate', 'HELLSING OVA', 'https://myanimelist.cdn-dena.com/images/anime/6/7333.jpg', 3, 'Manga', 10, 'Finished Airing', '2006-02-10', '2012-12-26', 50, 4, '8.53', 221939, 92, 105, 425255, 13450, 'Hellsing Ultimate was initially licensed and distributed by Geneon Entertainment USA up until their closure in late 2007. FUNimation Entertainment later picked up the series and finished dubbing it in late 2014.', null, null, null],
        [227, 'FLCL', 'FLCL', 'フリクリ', 'https://myanimelist.cdn-dena.com/images/anime/7/77356.jpg', 3, 'Original', 6, 'Finished Airing', '2000-04-26', '2001-03-16', 25, 3, '8.07', 231632, 460, 117, 406244, 15941, 'The original property rights of the anime were sold by Gainax to Production I.G in 2015. The anime placed third place for the Best Animation Film at the Fantasia Festival in 2003. In 2007 the anime got a nomination for Best Cast, and won the Best Comedy Series and the Best Short Series at the American Anime Awards show.', null, null, null],
        [16762, 'Mirai Nikki: Redial', 'The Future Diary: Redial', '未来日記リダイヤル', 'https://myanimelist.cdn-dena.com/images/anime/3/53247.jpg', 3, 'Manga', 1, 'Finished Airing', '2013-06-19', '2013-06-19', 29, 4, '7.62', 123067, 1305, 401, 190013, 462, 'The OVA received a special broadcast on NicoNico Douga on June 19, 2013. Bundled with the Mirai Nikki Redial manga volume on July 26, 2013.', null, null, null],
